from __future__ import annotations

from datetime import UTC, datetime
from enum import StrEnum
from zoneinfo import ZoneInfo

from sqlalchemy import select
from sqlalchemy.ext.asyncio import AsyncSession

from app.models.enums import SaleStatus
from app.models.sale import Sale


class SalePhase(StrEnum):
    UPCOMING = "upcoming"
    ACTIVE = "active"
    ENDED = "ended"


class InvalidSaleWindowError(Exception):
    """The sale's window collapses to a non-positive UTC range after zone conversion."""


def to_utc(local: datetime, tz_name: str) -> datetime:
    """Interpret a naive wall-clock time in the given IANA zone and return UTC."""
    return local.replace(tzinfo=ZoneInfo(tz_name)).astimezone(UTC)


def phase(starts_at: datetime, ends_at: datetime, now: datetime) -> SalePhase:
    """Derive the sale's display phase from its window and the current time."""
    if now < starts_at:
        return SalePhase.UPCOMING
    if now < ends_at:
        return SalePhase.ACTIVE
    return SalePhase.ENDED


async def create_sale(
    db: AsyncSession,
    title: str,
    price_minor: int,
    quantity: int,
    tz_name: str,
    starts_at_local: datetime,
    ends_at_local: datetime,
) -> Sale:
    starts_utc = to_utc(starts_at_local, tz_name)
    ends_utc = to_utc(ends_at_local, tz_name)
    if ends_utc <= starts_utc:
        raise InvalidSaleWindowError
    sale = Sale(
        title=title,
        price_minor=price_minor,
        quantity=quantity,
        available=quantity,
        starts_at=starts_utc,
        ends_at=ends_utc,
        timezone=tz_name,
        status=SaleStatus.ACTIVE.value,
    )
    db.add(sale)
    await db.commit()
    return sale


async def list_sales(db: AsyncSession) -> list[Sale]:
    return list((await db.scalars(select(Sale).order_by(Sale.starts_at))).all())


async def get_sale(db: AsyncSession, sale_id: int) -> Sale | None:
    result = await db.execute(select(Sale).where(Sale.id == sale_id))
    return result.scalar_one_or_none()
=== frontend useRealtime ===
// The one realtime composable: it owns the SSE connection to /api/events and
// its reconnect, and stores subscribe to it — no component ever opens a socket
// itself (frontend-vue rule). Listeners live at module scope so every store
// shares one EventSource and stays subscribed across a logout→login cycle;
// only the EventSource itself is closed (logout) and reopened (login).
//
// Native EventSource rather than VueUse useEventSource on purpose: useEventSource
// exposes only "latest value" refs (event/data are shallowRefs), so watching the
// event name drops two consecutive same-named events (two stock_changed in a row
// would deliver one callback). addEventListener fires per event, which is what
// live updates need. The browser's EventSource auto-reconnects, so no retry loop
// is needed here (see DECISIONS.md).

export const REALTIME_EVENTS = [
  'stock_changed',
  'sale_status',
  'order_status',
  'sale_stats',
] as const
export type RealtimeEvent = (typeof REALTIME_EVENTS)[number]

type Listener = (data: unknown) => void

export interface Realtime {
  on(event: RealtimeEvent, listener: Listener): void
  onReconnect(listener: () => void): void
}

const listeners = new Map<RealtimeEvent, Set<Listener>>()
const reconnectListeners = new Set<() => void>()
let source: EventSource | null = null

function parse(data: string): unknown {
  try {
    return JSON.parse(data)
  } catch {
    return null
  }
}

function open(): void {
  if (source) return
  const src = new EventSource('/api/events')

  for (const name of REALTIME_EVENTS) {
    src.addEventListener(name, (event: MessageEvent) => {
      const payload = parse(event.data)
      for (const listener of listeners.get(name) ?? []) listener(payload)
    })
  }

  // The first open is the initial connection; each later open is a reconnect,
  // so refetch before resuming the stream (a missed event is never shown).
  let opened = false
  src.onopen = () => {
    if (opened) {
      for (const listener of reconnectListeners) listener()
    }
    opened = true
  }

  source = src
}

export function useRealtime(): Realtime {
  open()
  return {
    on(event, listener) {
      const set = listeners.get(event) ?? new Set<Listener>()
      set.add(listener)
      listeners.set(event, set)
    },
    onReconnect(listener) {
      reconnectListeners.add(listener)
    },
  }
}

// Closes the EventSource (logout) without dropping the subscribed listeners, so
// the next openRealtime() re-attaches them to a fresh connection.
export function closeRealtime(): void {
  source?.close()
  source = null
}

export function openRealtime(): void {
  open()
}

